    /// <summary>Type path -> the verb names declared on it, in definition order (DM names, no C# renames).</summary>
    public static readonly ImmutableDictionary<string, ImmutableArray<string>> Verbs =
        ImmutableDictionary<string, ImmutableArray<string>>.Empty;

    /// <summary>typesof(/t/proc) for a type that tg enumerates; throws for any other type.</summary>
    public static ImmutableArray<string> ProcsOf(string typePath) =>
        Procs.TryGetValue(typePath, out ImmutableArray<string> names)
            ? names
            : throw new KeyNotFoundException("ProcOrder: tg does not enumerate typesof(" + typePath + "/proc); regenerate with tools/coloring");
}
